  self._ownReorder={title:setTitle,list:wiki.getTiddler(setTitle).fields.list};
  // Reuse the exact same interactive rows, preserving editor inputs and focus.
  if(self._orderDispose){self._orderDispose();self._orderDispose=null;}
  var byId=Object.create(null);
  Array.prototype.forEach.call(order.children,function(row){
   byId[row.getAttribute("data-repertoire-item")]=row;
  });
  safe.forEach(function(itemTitle,index){
   var row=byId[itemTitle];if(!row)return;
   order.appendChild(row);
   var number=row.querySelector(".huwrep-order-position");
   if(number)number.textContent=String(index+1).padStart(2,"0");
   row.classList.toggle("is-active",itemTitle===self.activeItem);
   var select=row.querySelector(".huwrep-order-title");
   if(select)select.setAttribute("aria-current",String(itemTitle===self.activeItem));
  });
  order.scrollTop=scrollTop;
  var position=editorPanel.querySelector(".huwrep-editor-position");
  if(position)position.textContent="NUMMER "+(safe.indexOf(self.activeItem)+1)+" AF "+safe.length;
  self._orderDispose=Reorder.mount(order,safe,onReorder);
  if(keyboard){
   var grip=byId[id]&&byId[id].querySelector(".huwrep-order-handle");
   if(grip&&grip.focus){
    try{grip.focus({preventScroll:true});}catch(_error){grip.focus();}
   }
  }
  // Guard against the browser's automatic scroll anchoring on DOM moves.
  if(win&&typeof win.scrollTo==="function"&&Number.isFinite(pageY)&&Math.abs(win.scrollY-pageY)>1){
   win.scrollTo(win.scrollX,pageY);
  }
 }
 this._orderDispose=Reorder.mount(order,list,onReorder);
};
Repertoire.prototype.refresh=function(changedTiddlers){
 var keys=Object.keys(changedTiddlers||{}),pending=this._ownReorder;
 if(this.scoreQueues){
  var wiki=this.wiki,imported=new Map();
  keys.forEach(function(title){
   var t=wiki.getTiddler(title),fields=t&&t.fields;
   if(fields&&fields["abc-source"]&&fields["abc-origin-entry"]){
    imported.set(fields["abc-origin-library"]+":"+fields["abc-origin-entry"],title);
   }
  });
  this.scoreQueues.forEach(function(queue,setTitle){
   var set=wiki.getTiddler(setTitle);
   if(!set||!imported.size)return;
   var additions=[];
   queue.forEach(function(item,key){
    var title=imported.get("musescore-bank:"+key);
    if(!title)return;
    additions.push(model.addItem(wiki,set.fields["orchestra-title"],title).title);
    queue.delete(key);
   });
   if(additions.length)model.setEntries(wiki,setTitle,model.entries(wiki,setTitle).concat(additions));
  });
 }
 // Reorder has already updated the existing rows; ignore only this exact
 // internal list write. Other edits or external changes must refresh normally.
 if(pending&&keys.length===1&&keys[0]===pending.title){
  var actual=this.wiki.getTiddler(pending.title);
  if(actual&&actual.fields.list===pending.list){this._ownReorder=null;return false;}
 }
 if(pending&&keys.indexOf(pending.title)>=0)this._ownReorder=null;
 var sourceTitles=this._sourceTitles||{};
 var affected=keys.some(function(title){return title.indexOf("Repertoire/")===0||sourceTitles[title];});
 if(affected){
  var keepFocus=this.document.activeElement===this.scoreSearch;
  this.refreshSelf();
  if(keepFocus&&this.scoreSearch)this.scoreSearch.focus();
  return true;
 }
 return false;
};
exports["huwiki-repertoire"]=Repertoire;
})();
"},"$:/plugins/huwiki/repertoire/styles.css":{"title":"$:/plugins/huwiki/repertoire/styles.css","type":"text/css","tags":["$:/tags/Stylesheet"],"text":".huwrep{max-width:1040px;margin:0 auto;line-height:1.5}
.huwrep h2{margin:0 0 .4rem}.huwrep h3{margin:.1rem 0 .5rem}
.huwrep-muted{color:#607078;font-size:.9em}.huwrep-status{padding:.6rem .75rem;border-left:3px solid #13745f;background:#edf8f2}
.huwrep-controls,.huwrep-inline,.huwrep-form{display:flex;gap:.6rem;flex-wrap:wrap;align-items:end;margin:.6rem 0}
.huwrep-controls{padding:.75rem;border:1px solid #c9d7d1;border-radius:.6rem}
.huwrep-panel{padding:1rem;margin:1rem 0;border:1px solid #cfddd8;border-radius:.7rem}
.huwrep-stand{border-color:#8cac9d;background:rgba(134,181,151,.08)}
.huwrep-field{display:flex;flex:1 1 170px;flex-direction:column;gap:.3rem;min-width:0;font-size:.92em;font-weight:600}
.huwrep-input{width:100%;min-width:0;padding:.5rem .6rem;border:1px solid #9baea8;border-radius:.4rem;font:inherit;color:inherit;background:var(--tc-background-color,#fff)}
.huwrep-button{padding:.4rem .6rem;border:1px solid #a9bcb5;background:transparent;color:inherit;border-radius:.4rem;cursor:pointer;font:inherit}
.huwrep-button:hover,.huwrep-button:focus-visible{border-color:#167356;outline-offset:2px}
.huwrep-button:disabled{opacity:.4;cursor:not-allowed}
.huwrep-primary{background:#175f4d;color:white;border-color:#175f4d}
.huwrep-link{text-align:left;border:0;text-decoration:underline;background:transparent}
.huwrep-item{display:flex;align-items:center;gap:.45rem;flex-wrap:wrap;padding:.35rem .2rem;border-bottom:1px solid #d8e4de}
.huwrep-list{padding-left:1.7rem;max-height:20rem;overflow:auto}
.huwrep-selected{background:rgba(26,134,95,.12)}
.huwrep-form textarea{min-height:5rem;resize:vertical}
@media(max-width:680px){.huwrep-panel{padding:.65rem}.huwrep-controls{padding:.6rem}.huwrep-field{flex-basis:100%}.huwrep-stand .huwrep-inline>select{flex:1 1 100%}.huwrep-button{min-height:42px}}

/* Repertoire selection: 1–3 columns according to available width. */
.huwrep-repertoire{background:var(--tc-background-color,#fff);container-type:inline-size}
.huwrep-repertoire-heading{display:flex;flex-wrap:wrap;justify-content:space-between;align-items:baseline;gap:.4rem 1rem}
.huwrep-repertoire-heading h3{margin:0;font-size:1.12em}
.huwrep-repertoire-count{color:#28614e;font-size:.86em;font-weight:700;white-space:nowrap}
.huwrep-repertoire-hint{margin:.25rem 0 .75rem;color:#596c62;font-size:.9em}
.huwrep-song-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:.55rem;list-style:none;margin:0;padding:0;max-height:none;overflow:visible}
.huwrep-song-item{min-width:0;margin:0;padding:0;list-style:none}
.huwrep .huwrep-song-card{position:relative;display:flex;flex-direction:column;justify-content:center;align-items:flex-start;box-sizing:border-box;min-height:66px;width:100%;padding:.7rem 2.15rem .7rem .75rem;text-align:left;line-height:1.35;font:inherit;font-size:.93em;font-weight:600;color:inherit;background:#fafcfa;border:1px solid #cbdcd2;border-radius:.55rem;overflow-wrap:anywhere;cursor:pointer;transition:background-color .12s ease,border-color .12s ease}
.huwrep .huwrep-song-card:hover{background:#eef7f1;border-color:#6aa084}
.huwrep .huwrep-song-card:focus-visible{outline:3px solid #337e62;outline-offset:2px}
.huwrep .huwrep-song-card.is-in-setlist{background:#eaf5ed;border-color:#4a9877;color:#164b3c}
.huwrep .huwrep-song-card:disabled{opacity:.58;cursor:default}
.huwrep-song-title{display:block;width:100%}
.huwrep-song-detail{display:block;margin-top:.18rem;color:#547066;font-weight:400;font-size:.88em}
.huwrep-song-indicator{position:absolute;right:.6rem;top:50%;transform:translateY(-50%);display:grid;place-items:center;width:1.35rem;height:1.35rem;box-sizing:border-box;border:1px solid #a4bcac;border-radius:50%;color:#53836a;background:#f5f9f6;font-size:1rem;font-weight:700;line-height:1}
.huwrep .is-in-setlist .huwrep-song-indicator{color:#fff;background:#176b53;border-color:#176b53}
@supports (container-type:inline-size){
 @container (max-width:720px){.huwrep-song-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}
 @container (max-width:450px){.huwrep-song-grid{grid-template-columns:minmax(0,1fr)}}
}
@supports not (container-type:inline-size){
 @media(max-width:900px){.huwrep-song-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}
 @media(max-width:570px){.huwrep-song-grid{grid-template-columns:1fr}}
}


/* Repertoire setlist: TW5 drag/drop highlight vocabulary, pointer-native input. */
.huwrep-stand{container-type:inline-size}
.huwrep-stand-layout{display:grid;grid-template-columns:minmax(240px,.93fr) minmax(0,1.5fr);gap:1.05rem;align-items:start;margin-top:.8rem}
.huwrep-order-panel,.huwrep-editor-panel{min-width:0;border:1px solid #d5e3db;border-radius:.7rem;background:var(--tc-background-color,#fff)}
.huwrep-order-panel{padding:.75rem .65rem}
.huwrep-editor-panel{padding:1rem}
.huwrep-order-heading{display:flex;align-items:baseline;justify-content:space-between;gap:.6rem;padding:0 .35rem}
.huwrep-order-heading h4{margin:0;font-size:1.06em}
.huwrep-order-hint{font-size:.81em;line-height:1.4;color:#63766b;margin:.25rem .35rem .75rem}
.huwrep-order-list{list-style:none;margin:0;padding:0;max-height:min(62dvh,560px);overflow-x:hidden;overflow-y:auto;overscroll-behavior:contain;-webkit-overflow-scrolling:touch;scrollbar-gutter:stable;touch-action:pan-y;scroll-behavior:auto;overflow-anchor:none}
.huwrep-order-list.huwrep-order-is-dragging{scroll-snap-type:none;user-select:none;-webkit-user-select:none}
.huwrep-order-row.tc-droppable{position:relative;display:grid;grid-template-columns:40px 25px minmax(0,1fr) 36px;align-items:center;gap:.24rem;min-height:46px;box-sizing:border-box;padding:.15rem .3rem;border-bottom:1px solid #e1e9e4;background:transparent}
.huwrep-order-row:last-child{border-bottom:0}
.huwrep-order-row.is-active{background:#e8f4ec;border-radius:.4rem}
.huwrep-order-row.tc-dragging{background:#e3eee6;opacity:.68;outline:1px dashed #3b8d69}
.huwrep-order-row.tc-dragover[data-drop-side="before"]:before,
.huwrep-order-row.tc-dragover[data-drop-side="after"]:after{position:absolute;content:"";left:0;right:0;height:4px;background:#187454;border-radius:4px;pointer-events:none;z-index:3}
.huwrep-order-row.tc-dragover[data-drop-side="before"]:before{top:-3px}
.huwrep-order-row.tc-dragover[data-drop-side="after"]:after{bottom:-3px}
.huwrep .huwrep-order-handle{touch-action:none;user-select:none;-webkit-user-select:none;cursor:grab;min-height:42px;min-width:38px;padding:0;line-height:1;font-size:1.35em;color:#557567;background:transparent;border:0}
.huwrep .huwrep-order-handle:active{cursor:grabbing}
.huwrep-order-position{font-variant-numeric:tabular-nums;color:#81938a;font-size:.78em;text-align:right}
.huwrep .huwrep-order-title{display:block;min-width:0;width:100%;padding:.45rem .2rem;text-align:left;font-size:.9em;font-weight:500;line-height:1.3;white-space:normal;overflow-wrap:anywhere;border:0;background:transparent}
.huwrep-order-row.is-active .huwrep-order-title{font-weight:700;color:#175d46}
.huwrep .huwrep-order-title:hover{text-decoration:underline}
.huwrep .huwrep-order-remove{border:0;background:transparent;color:#73847a;font-size:1.3em;line-height:1;min-width:36px;min-height:42px;padding:0}
.huwrep .huwrep-order-remove:hover{background:#f8e7e3;color:#963a2f}
.huwrep .huwrep-order-handle:focus-visible,
.huwrep .huwrep-order-title:focus-visible,
.huwrep .huwrep-order-remove:focus-visible{outline:2px solid #176b53;outline-offset:1px}
.huwrep-editor-position{font-size:.73em;letter-spacing:.065em;font-weight:700;color:#73877c}
.huwrep-editor-title{margin:.25rem 0 .25rem!important;line-height:1.25;font-size:1.22em}
.huwrep-source-hint{font-size:.82em;color:#65786d;margin:0 0 .65rem}
.huwrep-editor-fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:.75rem;align-items:start;margin:.6rem 0}
.huwrep-editor-fields .huwrep-field{flex:none;min-width:0}
.huwrep-editor-fields .huwrep-field:last-child{grid-column:1 / -1}
.huwrep-field-help{font-size:.77em;font-weight:400;color:#63796d}
.huwrep-editor-fields textarea{min-height:5.3rem}
.huwrep-editor-actions{margin:.8rem 0}
.huwrep-editor-actions .huwrep-button{white-space:normal;text-align:center}
.huwrep-editor-note{margin:.4rem 0 0;font-size:.8em}
@container (max-width:800px){
 .huwrep-stand-layout{grid-template-columns:1fr}
 .huwrep-order-panel,.huwrep-editor-panel{padding:.7rem}
}
@container (max-width:490px){
 .huwrep-editor-fields{grid-template-columns:1fr}
 .huwrep-editor-fields .huwrep-field{grid-column:1 / -1}
}
@supports not (container-type:inline-size){
 @media(max-width:1100px){.huwrep-stand-layout{grid-template-columns:1fr}}
 @media(max-width:650px){.huwrep-editor-fields{grid-template-columns:1fr}}
}
@media print{
 .huwrep-order-handle,.huwrep-order-remove{display:none!important}
 .huwrep-stand-layout{display:block}
}

/* Repertoire Nodebog – responsive reader, one ABC score loaded at a time. */
/* An editor suspends the book; its author display:flex must not override HTML hidden. */
.huwrep-book[hidden]{display:none!important}
.huwrep-book{position:relative;display:flex;flex-direction:column;gap:0;min-height:70vh;border:1px solid #c6d9d0;border-radius:10px;overflow:hidden;background:#f6faf7;color:#183c31;font:inherit}
.huwrep-book-header{position:relative;z-index:2;display:flex;flex-wrap:wrap;align-items:center;gap:8px;padding:8px;border-bottom:1px solid #d6e5dc;background:#edf5f0}
.huwrep-book-header>.huwrep-input{width:auto;flex:1 1 170px;max-width:100%}
.huwrep-book-heading{display:flex;align-items:baseline;justify-content:space-between;gap:10px;padding:8px 12px}
.huwrep-book-heading h2{margin:0;font-size:1.2em;line-height:1.3}
.huwrep-book-list{margin:0 8px 6px;padding:6px 8px;border:1px solid #d2e3d9;border-radius:7px;background:white}
.huwrep-book-list>summary{cursor:pointer;min-height:24px}
.huwrep-book-list-items{display:flex;flex-wrap:wrap;max-height:28vh;overflow:auto;gap:5px;padding:9px 0}
.huwrep-book-agreement{display:flex;flex-wrap:wrap;gap:8px;padding:6px 12px;font-size:0.9em;background:#e9f2e9}
.huwrep-book-agreement>span{border-left:2px solid #437a60;padding-left:7px}
.huwrep-book-transform-error{color:#963a2f!important;border-left-color:#963a2f!important}
.huwrep-book-form{max-width:100%;white-space:pre-wrap}
.huwrep-book-stage{display:flex;align-items:flex-start;justify-content:center;min-height:45vh;overflow:auto;background:#e7ece8;position:relative}
.huwrep-book-score{width:100%;min-width:0}
.huwrep-book-score .huwabc-page-shell{margin:6px!important;max-width:none}
.huwrep-book-image{display:block;max-width:100%;max-height:80vh;margin:auto;object-fit:contain}
.huwrep-book-footer{display:flex;gap:6px;align-items:center;justify-content:space-between;flex-wrap:wrap;padding:8px;background:#e9f3ec;border-top:1px solid #cfddd3}
.huwrep-book-footer>.huwrep-muted{margin:auto}
.huwrep-book-one-page .huwrep-book-view,.huwrep-book-one-page .huwrep-book-mode,.huwrep-book-one-page .huwrep-book-page-turn,.huwrep-book-one-page .huwrep-book-page-status{display:none!important}
.huwrep-book-fullscreen{position:fixed!important;inset:0!important;width:100vw!important;max-width:none!important;height:100dvh!important;min-height:0!important;z-index:10040!important;margin:0!important;border:0!important;border-radius:0!important;overflow:hidden!important}
.huwrep-book-fullscreen .huwrep-book-stage{flex:1;min-height:0}
.huwrep-book-fullscreen .huwrep-book-image{max-height:100%}
.huwrep-book-fullscreen .huwabc-page-shell{margin:0!important}
@media(max-width:780px){.huwrep-book-header{gap:5px;padding:6px}.huwrep-book-header>.huwrep-input{flex-basis:calc(50% - 8px);min-height:40px}.huwrep-book-heading{padding:6px}.huwrep-book-footer{gap:4px;padding:5px}.huwrep-book-footer>.huwrep-button{flex:1 1 35%;min-height:42px}}
@media print{.huwrep-book-header,.huwrep-book-list,.huwrep-book-footer{display:none!important}.huwrep-book{overflow:visible;border:0}.huwrep-book-stage{overflow:visible}}

/* Nodebog: discreet floating number drawer rather than a second score view. */
.huwrep-book-list[hidden]{display:none!important}
.huwrep-book-list{position:absolute;z-index:60;top:55px;right:8px;width:min(360px,calc(100% - 16px));max-height:min(78vh,740px);overflow:auto;box-sizing:border-box;box-shadow:0 12px 36px #122d2670;background:#fff;border:1px solid #a5c1b5;border-radius:9px;margin:0;padding:10px}
.huwrep-book-list-heading{display:flex;align-items:center;justify-content:space-between;gap:8px;margin-bottom:8px}
.huwrep-book-list-search{margin-bottom:8px}
.huwrep-book-list-items{display:flex;flex-direction:column;flex-wrap:nowrap;gap:4px;max-height:min(60vh,600px);overflow:auto;padding:0}
.huwrep-book-list-items>.huwrep-button{flex:none;min-height:42px;width:100%;white-space:normal;text-align:left}
.huwrep-book-list-items>.huwrep-button[hidden]{display:none!important}
.huwrep-book-practice{padding:6px 12px;border-bottom:1px solid #c9dace;background:#f4f8ee}
.huwrep-book-practice>summary{cursor:pointer;font-weight:650;list-style:revert;min-height:32px}
.huwrep-book-practice-controls{display:flex;flex-wrap:wrap;align-items:center;gap:12px;padding:8px 0}
.huwrep-book-practice-check{display:flex;align-items:center;gap:5px;min-height:40px}
.huwrep-book-practice-check input{width:20px;height:20px}
.huwrep-book-practice-voice{flex:1 1 250px;display:flex;flex-direction:column;gap:4px;font-size:.9em;font-weight:600}
.huwrep-book-practice-voice .huwrep-input{width:100%}
.huwrep-book-practice-controls>.huwrep-muted{flex:1 1 100%;margin:2px 0;font-size:.86em}
@media(max-width:760px){
 .huwrep-book-list{top:70px;max-height:72vh}
 .huwrep-book-practice-controls{gap:7px}
 .huwrep-book-header .huwrep-book-select{max-width:100%}
}

/* No double music stand: the repertoire book itself owns the immersive stage. */
.huwrep-book .huwabc-page-desk{display:none!important}

/* Hide unloaded iPad reader while the native editor owns the song. */
.huwrep-book[hidden]{display:none!important}
.huwrep-book-print-menu{position:relative;z-index:70;flex:0 0 auto}
.huwrep-book-print-menu>summary{list-style:none;cursor:pointer;border:1px solid #91b29d;border-radius:7px;padding:9px 12px;background:#fff;font-weight:650;min-height:42px;box-sizing:border-box}
.huwrep-book-print-menu>summary::-webkit-details-marker{display:none}
.huwrep-book-print-actions{position:absolute;z-index:75;top:calc(100% + 4px);left:0;display:flex;flex-direction:column;gap:5px;min-width:min(290px,85vw);padding:8px;background:#fff;border:1px solid #b3cbbd;border-radius:9px;box-shadow:0 12px 30px #132b2440}
.huwrep-book-print-actions button{text-align:left;white-space:normal}
@media(max-width:680px){.huwrep-book-print-actions{left:auto;right:0}}

/* One canonical title may offer original PDF pages and an editable ABC variant. */
.huwrep-library-filters{margin:.7rem 0;gap:.5rem}.huwrep-library-filters select{flex:1 1 170px}
.huwrep-song-formats{display:block;font-size:.73em;font-weight:650;color:#527463;margin-top:.3rem}
.huwrep-source-options{margin:.5rem 0;padding:.5rem;border:1px solid #cbdbd1;border-radius:6px;background:#fff}
.huwrep-source-options>summary{cursor:pointer;font-weight:650}.huwrep-source-options>.huwrep-field{margin:.6rem 0}
.huwrep-book-pdf{width:100%;min-width:0;display:flex;flex-direction:column;align-self:stretch}
.huwrep-book-pdf-frame{display:block;width:100%;height:75vh;min-height:420px;border:0;background:#dce5de}
.huwrep-book-pdf-status,.huwrep-book-pdf-link{margin:.5rem 1rem}.huwrep-book-pdf-status[hidden]{display:none!important}
.huwrep-book-fullscreen .huwrep-book-pdf{height:100%}.huwrep-book-fullscreen .huwrep-book-pdf-frame{flex:1;height:100%;min-height:0}
.huwrep-book-source{max-width:25rem}.huwrep-error{color:#9b312b}
"},"HUWiki Repertoire – Start":{"title":"HUWiki Repertoire – Start","type":"text/vnd.tiddlywiki","caption":"Repertoire","huwiki-title-da":"Repertoire","huwiki-title-en":"Repertoire","text":"
